  const k = n.args.length
  if (name === 'IF') {
    if (k !== 3) return err('#ERR!')
    const c = ev(n.args[0])
    if (isErr(c)) return c
    let t
    if (c.type === 'bool') t = c.v
    else if (c.type === 'num') t = c.v !== 0
    else return err('#VALUE!')
    return ev(n.args[t ? 1 : 2])
  }
  if (name === 'ABS') {
    if (k !== 1) return err('#ERR!')
    const vals = n.args[0].k === 'range' ? expand(n.args[0]) : [ev(n.args[0])]
    const e = vals.find(isErr)
    if (e) return e
    if (vals.length !== 1) return err('#ERR!')
    const x = toNum(vals[0])
    return isErr(x) ? x : num(Math.abs(x.v))
  }
  if (!AGG.includes(name)) return err('#NAME?')
  const vals = []
  for (const a of n.args) {
    if (a.k === 'range') vals.push(...expand(a))
    else vals.push(ev(a))
  }
  const e = vals.find(isErr)
  if (e) return e
  if (name === 'COUNT') return num(vals.filter((v) => v.type === 'num').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (isErr(x)) return x
    nums.push(x.v)
  }
  if (name === 'SUM') return finite(nums.reduce((s, x) => s + x, 0))
  if (name === 'MIN') return num(Math.min(...nums))
  if (name === 'MAX') return num(Math.max(...nums))
  return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
}

function show(v) {
  if (v.type === 'num') return String(Number(v.v.toPrecision(10)))
  if (v.type === 'err') return v.e
  if (v.type === 'bool') return v.v ? 'TRUE' : 'FALSE'
  return v.v
}

let out = ''
for (const c of sorted) out += `${c.key}=${show(cellValue(c.key))}\n`
process.stdout.write(out)
"}

