    const f = parsed.get(c.key)
    if (f) collectAddrs(f.ast, m)
    const list = [...m.values()].sort((x, y) => x.col - y.col || x.row - y.row)
    out += c.key + ':' + list.map((a) => ' ' + a.key).join('') + '\n'
  }
  process.stdout.write(out)
  process.exit(0)
}

// ---- evaluation
const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (e) => ({ type: 'err', e })
const num = (v) => ({ type: 'num', v })
const isErr = (v) => v.type === 'err'
const memo = new Map()
const stack = new Set()

function cellValue(key) {
  if (memo.has(key)) return memo.get(key)
  const c = cells.get(key)
  if (!c) return num(0)
  if (stack.has(key)) return err('#CYCLE!')
  stack.add(key)
  let v
  const s = c.content
  if (s[0] === '=') {
    const f = parsed.get(key)
    v = !f || f.misplaced ? err('#ERR!') : ev(f.ast)
  } else if (s === '') v = num(0)
  else if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) v = num(Number(s))
  else if (ERRS.includes(s)) v = err(s)
  else v = { type: 'text', v: s }
  stack.delete(key)
  memo.set(key, v)
  return v
}

function toNum(v) {
  if (v.type === 'num') return v
  if (v.type === 'bool') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}
const finite = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))
const rank = { num: 0, text: 1, bool: 2 }

function expand(node) {
  const a = parseAddr(node.a), b = parseAddr(node.b)
  if (!a || !b) return [err('#REF!')]
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push(cellValue(colName(c) + r))
  return out
}

function cpCompare(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}

function ev(n) {
  switch (n.k) {
    case 'num': return num(n.v)
    case 'bool': return { type: 'bool', v: n.v }
    case 'ref': {
      const a = parseAddr(n.w)
      return a ? cellValue(a.key) : err('#REF!')
    }
    case 'range': return err('#ERR!')
    case 'un': {
      const v = ev(n.e)
      if (isErr(v)) return v
      const x = toNum(v)
      if (isErr(x)) return x
      return n.op === '-' ? num(-x.v) : x
    }
    case 'bin': {
      const l = ev(n.l)
      if (isErr(l)) return l
      const r = ev(n.r)
      if (isErr(r)) return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        let c
        if (l.type !== r.type) c = rank[l.type] - rank[r.type]
        else if (l.type === 'text') c = cpCompare(l.v, r.v)
        else c = Number(l.v) < Number(r.v) ? -1 : Number(l.v) > Number(r.v) ? 1 : 0
        const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
        return { type: 'bool', v: res }
      }
      const a = toNum(l)
      if (isErr(a)) return a
      const b = toNum(r)
      if (isErr(b)) return b
      switch (n.op) {
        case '+': return finite(a.v + b.v)
        case '-': return finite(a.v - b.v)
        case '*': return finite(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
        default: return finite(Math.pow(a.v, b.v))
      }
    }
    default: return call(n)
  }
}

const AGG = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
function call(n) {
  const name = n.name
  const k = n.args.length
  if (name === 'IF') {
    if (k !== 3) return err('#ERR!')
    const c = ev(n.args[0])
    if (isErr(c)) return c
    let t
    if (c.type === 'bool') t = c.v
    else if (c.type === 'num') t = c.v !== 0
    else return err('#VALUE!')
    return ev(n.args[t ? 1 : 2])
  }
  if (name === 'ABS') {
    if (k !== 1) return err('#ERR!')
    const vals = n.args[0].k === 'range' ? expand(n.args[0]) : [ev(n.args[0])]
    const e = vals.find(isErr)
    if (e) return e
    if (vals.length !== 1) return err('#ERR!')
    const x = toNum(vals[0])
    return isErr(x) ? x : num(Math.abs(x.v))
  }
  if (!AGG.includes(name)) return err('#NAME?')
  const vals = []
  for (const a of n.args) {
    if (a.k === 'range') vals.push(...expand(a))
    else vals.push(ev(a))
  }
  const e = vals.find(isErr)
  if (e) return e
  if (name === 'COUNT') return num(vals.filter((v) => v.type === 'num').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (isErr(x)) return x
    nums.push(x.v)
  }
  if (name === 'SUM') return finite(nums.reduce((s, x) => s + x, 0))
  if (name === 'MIN') return num(Math.min(...nums))
  if (name === 'MAX') return num(Math.max(...nums))
  return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
}

function show(v) {
  if (v.type === 'num') return String(Number(v.v.toPrecision(10)))
  if (v.type === 'err') return v.e
  if (v.type === 'bool') return v.v ? 'TRUE' : 'FALSE'
  return v.v
}

let out = ''
for (const c of sorted) out += `${c.key}=${show(cellValue(c.key))}\n`
process.stdout.write(out)
